def parse_flag(value, *, default=False):
    """Parse a bool or supported string; None uses default, others raise ValueError."""
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in ("true", "1", "yes", "on"):
            return True
        if normalized in ("false", "0", "no", "off"):
            return False
    raise ValueError("feature flag must be a boolean or a supported boolean string")

import unittest

from atlas.config import parse_flag
from atlas.service import DocumentService


class FeatureFlagTests(unittest.TestCase):
    def test_booleans_are_preserved(self):
        for value in (True, False):
            with self.subTest(value=value):
                self.assertIs(parse_flag(value, default=not value), value)

    def test_supported_strings(self):
        service = DocumentService()
        for expected, tokens in (
            (True, ("true", "1", "yes", "on")),
            (False, ("false", "0", "no", "off")),
        ):
            for token in tokens:
                for value in (token, token.upper(), " \t" + token.title() + "\n"):
                    with self.subTest(value=value):
                        self.assertIs(parse_flag(value, default=not expected), expected)
                        self.assertIs(service.feature_enabled(value), expected)

    def test_null_uses_default(self):
        self.assertIs(parse_flag(None), False)
        for default in (True, False):
            with self.subTest(default=default):
                self.assertIs(parse_flag(None, default=default), default)

    def test_invalid_values_are_rejected(self):
        service = DocumentService()
        for value in (
            0, 1, -1, 2, 0.0, 1.0, complex(1), float("nan"),
            "", " \t\n", "enabled", "disabled", "2", "true false",
            [], [True], {}, {"enabled": True}, (), set(), b"true", object(),
        ):
            with self.subTest(value=value):
                for default in (True, False):
                    with self.assertRaises(ValueError):
                        parse_flag(value, default=default)
                with self.assertRaises(ValueError):
                    service.feature_enabled(value)

    def test_service_booleans_and_null(self):
        service = DocumentService()
        for value in (True, False, None):
            with self.subTest(value=value):
                self.assertIs(service.feature_enabled(value), value is True)
